{{ config(
            materialized='table',
                post_hook={
                    "sql": "ALTER SESSION SET TIMEZONE = \'Asia/Kolkata\'; CREATE OR REPLACE TABLE SNITCH_DB.maplemonk.snitch_db_NPS_REPORT as ( with product_review as ( select replace(shopify_user_id,\',\',\'\') as shopify_user_id, replace(shopify_product_id,\',\',\'\') as shopify_product_id, shopify_product_type, created_at, rating, review from snitch_db.maplemonk.gs_product_review ), id as ( select id, sku_group from snitch_db.maplemonk.availability_master_v2 qualify row_number() over (partition by sku_group order by sellable_inventory desc) = 1 ), product_review_final as ( select a.*, b.sku_group from product_review a left join id b on a.shopify_product_id = b.id ), order_date as ( select order_timestamp::date as order_date, customer_id, sku_group, order_name from snitch_db.maplemonk.fact_items_snitch qualify row_number() over (partition by customer_id,sku_group order by order_timestamp::date desc) = 1 ), product_ratings as ( select a.*, b.order_date, b.order_name from product_review_final a left join order_date b on a.shopify_user_id = b.customer_id and a.sku_group = b.sku_group ), order_level_product_rating as ( select order_name, avg(rating) as product_rating, LISTAGG(review, \', \') WITHIN GROUP (ORDER BY review) AS product_reviews from product_ratings group by 1 ), NPS_DATA AS ( SELECT TO_TIMESTAMP(Created_At, \'MMMM DD, YYYY, HH24:MI\')::date AS NPS_responce_Date, CASE WHEN LOWER(Form_Type) = \'return_order\' THEN \'RETURN\' WHEN LOWER(Form_Type) = \'online_order\' THEN \'FORWARD\' ELSE \'STORE\' END AS FORM_TYPE, Trigger_Event AS trigger_event, CASE WHEN REPLACE(Shopify_Order_Number,\',\',\'\') IS NULL THEN SPLIT_PART(Bill_No, \'-\', -1) ELSE REPLACE(Shopify_Order_Number,\',\',\'\') END AS order_name, case when LOWER(Form_Type) = \'online_order\' then Delivery_Rating when LOWER(Form_Type) = \'return_order\' then RETURN_EXPERIENCE_RATING else STORE_EXPERIENCE_RATING end as nps_score, product_rating, product_reviews, Delivery_Rating AS Delivery_Rating, Store_Experience_Rating AS store_experience_rating, Return_Experience_Rating AS Return_Experience_rating FROM snitch_db.maplemonk.gs_nps_metabase a left join order_level_product_rating b on CASE WHEN REPLACE(Shopify_Order_Number,\',\',\'\') IS NULL THEN SPLIT_PART(Bill_No, \'-\', -1) ELSE REPLACE(Shopify_Order_Number,\',\',\'\') END = b.order_name ), Clickpost_data AS ( SELECT order_id AS order_name, CASE WHEN JOURNEY = \'Reverse\' THEN \'RETURN\' ELSE \'FORWARD\' END AS type, phone, email, customer_name, pickup_date::date AS pickup_date, delivery_date::date AS delivery_date, order_date::date AS order_date FROM snitch_db.maplemonk.cp_1 WHERE order_id IN (SELECT order_name FROM NPS_DATA) QUALIFY ROW_NUMBER() OVER (PARTITION BY order_id, type ORDER BY delivery_date DESC) = 1 ), main_data AS ( SELECT a.*, b.phone, b.email, b.customer_name, b.pickup_date, b.delivery_date, b.order_date FROM NPS_DATA a LEFT JOIN Clickpost_data b ON a.order_name = b.order_name AND a.form_type = b.type ), monthly_orders AS ( SELECT CASE WHEN JOURNEY = \'Reverse\' THEN \'RETURN\' ELSE \'FORWARD\' END AS type, CASE WHEN JOURNEY = \'Reverse\' THEN pickup_date::date ELSE delivery_date::date END AS delivery_date, COUNT(DISTINCT order_id) AS total_orders FROM snitch_db.maplemonk.cp_1 GROUP BY 1, 2 UNION ALL SELECT \'STORE\' AS type, order_date AS delivery_date, COUNT(DISTINCT order_name) AS total_orders FROM snitch_db.maplemonk.STORE_fact_items_offline WHERE marketplace_mapped NOT LIKE \'%WH%\' AND LOWER(sku_group) NOT LIKE \'cb%\' AND order_date IS NOT NULL GROUP BY 1, 2 ), CleverTap_Data AS ( SELECT CASE WHEN LOWER(Campaign_Name) LIKE \'%forward%\' THEN \'FORWARD\' WHEN Campaign_Name IN (\'Return NPS\',\'NPS Return\',\'NPS Return 21st Jan\') THEN \'RETURN\' WHEN Campaign_Name IN (\'NPS offline (Variant B)\',\'NPS offline\') THEN \'STORE\' END AS type, TRY_TO_DATE( REGEXP_REPLACE(REGEXP_REPLACE(run_date, \'^(\d{1})/\', \'0\\1/\'), \'/(\d{1})/\', \'/0\\1/\'), \'DD/MM/YYYY\' ) AS notification_date, SUM(IFNULL(TOTAL_SENT_USERS, 0))::int AS TOTAL_SENT_USERS, SUM(IFNULL(TOTAL_VIEWED_USERS, 0))::int AS TOTAL_VIEWED_USERS, SUM(IFNULL(TOTAL_CLICKED_USERS, 0))::int AS TOTAL_CLICKED_USERS FROM snitch_db.maplemonk.CT_clevertap_db WHERE LOWER(Campaign_Name) LIKE \'%nps%\' AND Campaign_Name != \'Post_NPS_UGC\' AND TRY_TO_DATE( REGEXP_REPLACE(REGEXP_REPLACE(run_date, \'^(\d{1})/\', \'0\\1/\'), \'/(\d{1})/\', \'/0\\1/\'), \'DD/MM/YYYY\' ) IS NOT NULL AND LOWER(channel) = \'whatsapp\' GROUP BY 1, 2 ) SELECT a.type, a.delivery_date, a.total_orders, b.TOTAL_SENT_USERS, b.TOTAL_VIEWED_USERS, b.TOTAL_CLICKED_USERS, a.total_orders - b.TOTAL_SENT_USERS AS UNSENT_USERS FROM monthly_orders a LEFT JOIN CleverTap_Data b ON a.type = b.type AND a.delivery_date + 1 = b.notification_date WHERE a.total_orders - b.TOTAL_SENT_USERS IS NOT NULL ORDER BY a.delivery_date DESC ); create or replace table snitch_db.maplemonk.nps_google_sheet as with product_review as ( select replace(shopify_user_id,\',\',\'\') as shopify_user_id, replace(shopify_product_id,\',\',\'\') as shopify_product_id, shopify_product_type, created_at, rating, review from snitch_db.maplemonk.gs_product_review ), id as ( select id, sku_group from snitch_db.maplemonk.availability_master_v2 qualify row_number() over (partition by sku_group order by sellable_inventory desc) = 1 ), product_review_final as ( select a.*, b.sku_group from product_review a left join id b on a.shopify_product_id = b.id ), order_date as ( select order_timestamp::date as order_date, customer_id, sku_group, order_name from snitch_db.maplemonk.fact_items_snitch qualify row_number() over (partition by customer_id,sku_group order by order_timestamp::date desc) = 1 ), product_ratings as ( select a.*, b.order_date, b.order_name from product_review_final a left join order_date b on a.shopify_user_id = b.customer_id and a.sku_group = b.sku_group ), store_details as ( select distinct split_part(order_name,\'-\',-1) as order_name, marketplace_mapped as store from snitch_db.maplemonk.STORE_fact_items_offline ), order_level_product_rating as ( select order_name, LISTAGG(review, \', \') WITHIN GROUP (ORDER BY review) AS product_reviews, avg(rating) as product_rating from product_ratings group by 1 ) SELECT TO_TIMESTAMP(Created_At, \'MMMM DD, YYYY, HH24:MI\')::date AS NPS_responce_Date, CASE WHEN LOWER(Form_Type) = \'return_order\' THEN \'RETURN\' WHEN LOWER(Form_Type) = \'online_order\' THEN \'FORWARD\' WHEN LOWER(Form_Type) = \'store_order\' THEN \'STORE\' END AS FORM_TYPE, Trigger_Event AS trigger_event, CASE WHEN REPLACE(Shopify_Order_Number,\',\',\'\') IS NULL THEN SPLIT_PART(Bill_No, \'-\', -1) ELSE REPLACE(Shopify_Order_Number,\',\',\'\') END AS order_name, case when LOWER(Form_Type) = \'online_order\' then Delivery_Rating when LOWER(Form_Type) = \'return_order\' then RETURN_EXPERIENCE_RATING WHEN LOWER(Form_Type) = \'store_order\' THEN STORE_EXPERIENCE_RATING end as nps_score, product_rating, product_reviews, Delivery_Rating AS Delivery_Rating, Store_Experience_Rating AS store_experience_rating, store, Return_Experience_Rating AS Return_Experience_rating FROM snitch_db.maplemonk.gs_nps_metabase a left join order_level_product_rating b on CASE WHEN REPLACE(Shopify_Order_Number,\',\',\'\') IS NULL THEN SPLIT_PART(Bill_No, \'-\', -1) ELSE REPLACE(Shopify_Order_Number,\',\',\'\') END = b.order_name left join store_details c on CASE WHEN REPLACE(Shopify_Order_Number,\',\',\'\') IS NULL THEN SPLIT_PART(Bill_No, \'-\', -1) ELSE REPLACE(Shopify_Order_Number,\',\',\'\') END = c.order_name ;",
                    "transaction": true
                }
            ) }}
